   324→        private static void UpdateMetrics(ExecutionOptions opts, UInt256 effectiveGasPrice)
   325→        {
   326→            if (opts is ExecutionOptions.Commit or ExecutionOptions.None && (effectiveGasPrice[2] | effectiveGasPrice[3]) == 0)
   327→            {
   328→                float gasPrice = (float)((double)effectiveGasPrice / 1_000_000_000.0);
   329→
   330→                Metrics.BlockMinGasPrice = Math.Min(gasPrice, Metrics.BlockMinGasPrice);
   331→                Metrics.BlockMaxGasPrice = Math.Max(gasPrice, Metrics.BlockMaxGasPrice);
   332→
   333→                Metrics.BlockAveGasPrice = (Metrics.BlockAveGasPrice * Metrics.BlockTransactions + gasPrice) / (Metrics.BlockTransactions + 1);
   334→                Metrics.BlockEstMedianGasPrice += Metrics.BlockAveGasPrice * 0.01f * float.Sign(gasPrice - Metrics.BlockEstMedianGasPrice);
   335→                Metrics.BlockTransactions++;
   336→            }
